def hullmask(track_ranges, inp, actual):
  offs=sorted(track_ranges)
  pred=set()
  for i,a in enumerate(offs):
   for b in offs[i+1:]:
    alo,ahi=track_ranges[a]; blo,bhi=track_ranges[b]
    for r in range(16):
     for c in range(16):
      if inp[r][c] != 8: continue
      d=c-r;s=c+r
      if not a<d<b: continue
      t=(d-a)/(b-a)
      low=alo+(blo-alo)*t
      high=ahi+(bhi-ahi)*t
      if low<=s<=high: pred.add((r,c))
  return pred
